 void callbacks(){glfwSetScrollCallback(window,(win,sx,sy)->ViewControls.adjustFlySpeed(sy));glfwSetMouseButtonCallback(window,(win,button,action,mods)->{if(button==GLFW_MOUSE_BUTTON_LEFT&&action==GLFW_PRESS){grabbed=true;mouseReady=false;rawMouse=ViewControls.captureMouse(win);captureTime=System.nanoTime();motionEvents=0;}});glfwSetCursorPosCallback(window,(win,xx,yy)->{if(grabbed)motionEvents++;if(grabbed&&mouseReady){double look=.0025*ViewControls.sensitivity();yaw+=ViewControls.delta(xx-lastX)*look;pitch=Math.max(-1.55,Math.min(1.55,pitch-ViewControls.delta(yy-lastY)*look));}lastX=xx;lastY=yy;mouseReady=true;});glfwSetKeyCallback(window,(win,k,scan,action,mods)->{if(action!=GLFW_PRESS)return;if(k==GLFW_KEY_ESCAPE){if(grabbed){grabbed=false;ViewControls.releaseMouse(win);}else glfwSetWindowShouldClose(win,true);}if(k==GLFW_KEY_F1)hud=!hud;if(k==GLFW_KEY_LEFT_BRACKET||k==GLFW_KEY_RIGHT_BRACKET)ViewControls.adjustSensitivity(k==GLFW_KEY_RIGHT_BRACKET);if(k==GLFW_KEY_F&&wholeMap)fitWhole();if(k==GLFW_KEY_R)requestMesh();if(k==GLFW_KEY_G){grabbed=false;ViewControls.releaseMouse(win);SwingUtilities.invokeLater(()->{JTextField xx=new JTextField(Integer.toString((int)x+world.originX)),zz=new JTextField(Integer.toString((int)z+world.originZ));JPanel panel=new JPanel(new java.awt.GridLayout(2,2));panel.add(new JLabel("X"));panel.add(xx);panel.add(new JLabel("Z"));panel.add(zz);if(JOptionPane.showConfirmDialog(null,panel,"Go to map coordinates",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{teleport.set(new double[]{Double.parseDouble(xx.getText()),Double.parseDouble(zz.getText())});}catch(NumberFormatException e){JOptionPane.showMessageDialog(null,"Enter numeric map coordinates.");}});}if(k==GLFW_KEY_P)SwingUtilities.invokeLater(()->{JFileChooser c=new JFileChooser();c.setSelectedFile(new java.io.File("Minecraft-view-4K.png"));if(c.showSaveDialog(null)==JFileChooser.APPROVE_OPTION){Path p=c.getSelectedFile().toPath();if(!p.toString().toLowerCase(Locale.ROOT).endsWith(".png"))p=Path.of(p+".png");if(!Files.exists(p)||JOptionPane.showConfirmDialog(null,"Replace "+p.getFileName()+"?","Save",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)screenshot.set(p);}});if(k==GLFW_KEY_EQUAL||k==GLFW_KEY_MINUS||k==GLFW_KEY_KP_ADD||k==GLFW_KEY_KP_SUBTRACT){radius=Math.max(64,Math.min(512,radius+(k==GLFW_KEY_EQUAL||k==GLFW_KEY_KP_ADD?32:-32)));requestMesh();}if(k==GLFW_KEY_F11){if(glfwGetWindowMonitor(win)==0){long monitor=glfwGetPrimaryMonitor();var mode=glfwGetVideoMode(monitor);glfwSetWindowMonitor(win,monitor,0,0,mode.width(),mode.height(),mode.refreshRate());}else glfwSetWindowMonitor(win,0,60,60,1600,1000,0);}});}
 void capture(Path path)throws Exception{int width=4096,height=4096,fbo=glGenFramebuffers(),color=glGenTextures(),depth=glGenRenderbuffers();glBindFramebuffer(GL_FRAMEBUFFER,fbo);try{glBindTexture(GL_TEXTURE_2D,color);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,width,height,0,GL_RGBA,GL_UNSIGNED_BYTE,(ByteBuffer)null);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,color,0);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT24,width,height);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw new IllegalStateException("4K framebuffer unavailable");draw(width,height);ByteBuffer data=MemoryUtil.memAlloc(width*height*4);try{glReadPixels(0,0,width,height,GL_RGBA,GL_UNSIGNED_BYTE,data);BufferedImage image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);int[] out=((DataBufferInt)image.getRaster().getDataBuffer()).getData();for(int yy=0;yy<height;yy++)for(int xx=0;xx<width;xx++){int i=((height-1-yy)*width+xx)*4;out[yy*width+xx]=(data.get(i)&255)<<16|(data.get(i+1)&255)<<8|(data.get(i+2)&255);}Files.createDirectories(path.toAbsolutePath().getParent());ImageIO.write(image,"png",path.toFile());System.out.println("MINECRAFT_VIEW_4K_SAVED: "+path);}finally{MemoryUtil.memFree(data);}}finally{glBindFramebuffer(GL_FRAMEBUFFER,0);glDeleteFramebuffers(fbo);glDeleteTextures(color);glDeleteRenderbuffers(depth);}}
 public static void main(String[] args)throws Exception{TerraForge.World w;if(args[0].equals("--test")){w=TerraForge.generateWorld(256,62,2024,120,"Island");var tree=new TerrainGraph.Node(1,TerrainGraph.Type.TREES,0,0);tree.values.put("group",28.0);tree.values.put("variant",55.0);tree.values.put("minY",63.0);tree.values.put("maxY",250.0);tree.values.put("slope",3.0);w.environment=TreeLibrary.scatter(tree,w.environment,null,w.size,w.size,w.sea,w.seed,()->false);}else w=TerraForge.readProject(Path.of(args[0]));var preview=new MinecraftPreview();preview.wholeMap=Boolean.getBoolean("terraforge.wholeMapBlocks");preview.run(w,MinecraftAssets.locate(),args.length>1?Path.of(args[1]):null,args.length>2&&args[2].equals("--exit"));}
